(()=>{const A=Abibi,page=document.body.dataset.page;
const progress=()=>{const t=A.tier();return `<div class="level-meta"><strong>${t.current.name}</strong><span>${t.next?'سطح بعد: '+t.next.name:'بالاترین سطح'}</span></div><div class="progress" role="progressbar" aria-label="پیشرفت تا سطح بعدی" aria-valuenow="${Math.round(t.percent)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:${t.percent}%"></div></div><p class="level-note">${t.next?`فقط <strong>${A.fa(t.remaining)} امتیاز سطح</strong> تا عضویت ${t.next.name} باقی مانده.`:'به بالاترین سطح نمایشی رسیده‌ای.'}</p><small class="text-muted">امتیاز تجمعی تعیین سطح: ${A.fa(A.state.qualifying)}</small>`};
function rewards(limit){return A.D.club.rewards.slice(0,limit||99).map(r=>{const got=A.state.coupons.some(c=>c.rewardId===r.id),enough=A.state.points>=r.cost;return `<div class="col-md-6 col-xl-4"><article class="reward-card"><img src="assets/image/${r.image}" alt="${r.name}"><div class="content"><h3>${r.name}</h3><p>${r.desc}</p><strong class="d-block text-primary mb-3">${A.fa(r.cost)} امتیاز</strong><button type="button" class="btn btn-primary w-100" data-redeem="${r.id}" ${got||!enough?'disabled':''}>${got?'دریافت شده':enough?'دریافت پاداش':A.fa(r.cost-A.state.points)+' امتیاز کم داری'}</button></div></article></div>`}).join('')}
function stats(){return [['امتیاز قابل استفاده',A.fa(A.state.points)],['سطح عضویت',A.tier().current.name],['تا سطح بعدی',A.fa(A.tier().remaining)+' امتیاز']].map(([label,value])=>`<div class="col-6 col-md-4"><div class="stat-card"><small>${label}</small><strong class="metric">${value}</strong></div></div>`).join('')}
function render(){A.sync();for(const selector of ['#club-progress','#level-progress'])if(A.$(selector))A.$(selector).innerHTML=progress();for(const selector of ['#club-stats','#points-stats'])if(A.$(selector))A.$(selector).innerHTML=stats();if(A.$('#club-rewards'))A.$('#club-rewards').innerHTML=rewards(3);if(A.$('#rewards-list'))A.$('#rewards-list').innerHTML=rewards();if(A.$('#tier-cards'))A.$('#tier-cards').innerHTML=A.D.club.tiers.map((t,i)=>`<div class="col-sm-6"><article class="tier-card ${A.tier().current.name===t.name?'current':''}"><span class="tier-symbol">${['◇','◈','✦','❖'][i]}</span><h3>${t.name}</h3><p class="text-muted small">از ${A.fa(t.min)} امتیاز سطح</p>${A.tier().current.name===t.name?'<span class="badge text-bg-dark mb-3">سطح فعلی شما</span>':''}<ul><li>دسترسی به باشگاه و پاداش‌ها</li>${i>0?'<li>پیشنهادهای اختصاصی سطح (نمونه)</li>':''}${i>1?'<li>هدیه مناسبتی (نمونه)</li>':''}${i>2?'<li>دعوت به تجربه محصولات جدید (نمونه)</li>':''}</ul></article></div>`).join('');if(A.$('#points-list')){const filter=A.$('#points-filter').value;const items=A.state.ledger.filter(x=>filter==='all'||(filter==='earn'?x.amount>0:x.amount<0));A.$('#points-list').innerHTML=items.length?items.map(x=>`<tr><td>${A.esc(x.label)}</td><td>${A.date(x.date)}</td><td class="${x.amount>0?'point-earn':'point-spend'}" dir="ltr">${x.amount>0?'+':'−'}${A.fa(Math.abs(x.amount))}</td><td>${x.amount>0?'دریافت':'خرج'}</td></tr>`).join(''):'<tr><td colspan="4" class="text-center text-muted py-4">تراکنشی با این فیلتر وجود ندارد.</td></tr>'}if(A.$('#coupons-list'))A.$('#coupons-list').innerHTML=A.state.coupons.length?A.state.coupons.map(c=>`<div class="col-md-6"><article class="coupon"><span class="badge text-bg-light mb-2">کوپن نمایشی</span><h2 class="h5">${A.esc(c.name)}</h2><code>${A.esc(c.code)}</code><p class="small text-muted">دریافت‌شده در ${A.date(c.date)} · ${A.fa(c.cost)} امتیاز</p><button class="btn btn-outline-primary w-100" type="button" data-copy="${c.code}">کپی کد</button><small class="text-muted d-block mt-3">این کد قابل استفاده در خرید واقعی نیست.</small></article></div>`).join(''):`<div class="col-12 surface">${A.empty('هنوز کوپنی نداری','از امتیازهایت برای دریافت پاداش استفاده کن.','rewards.html','مشاهده پاداش‌ها')}</div>`}
render();A.$('#points-filter')?.addEventListener('change',render);document.addEventListener('abibi:change',render);document.addEventListener('click',async e=>{const b=e.target.closest('[data-redeem]');if(b){const reward=A.D.club.rewards.find(r=>r.id===b.dataset.redeem);if(!reward||A.state.coupons.some(c=>c.rewardId===reward.id)||A.state.points<reward.cost)return;if(!confirm(`برای دریافت «${reward.name}»، ${A.fa(reward.cost)} امتیاز کسر می‌شود. ادامه می‌دهی؟`))return;A.state.points-=reward.cost;const now=new Date().toISOString();A.state.ledger.unshift({id:A.id(),label:'دریافت '+reward.name,amount:-reward.cost,date:now});A.state.coupons.unshift({id:A.id(),rewardId:reward.id,name:reward.name,code:'DEMO-'+A.id().replace(/-/g,'').slice(0,8).toUpperCase(),cost:reward.cost,date:now});A.save();A.toast('پاداش به کوپن‌های من اضافه شد')}const copy=e.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy);A.toast('کد کپی شد')}catch{A.toast('کپی خودکار در دسترس نیست؛ کد را از کادر انتخاب و کپی کن.')}}})})();
